const text = String($json.text || '').trim();
const hadVoice = !!$json.hadVoice;
const voiceError = String($json.voiceError || '').trim();
let intent = 'chat';

const isVoiceFail = hadVoice && (!!voiceError || /^\[áudio recebido/i.test(text));
if (isVoiceFail) {
  return [{ json: { ...$json, intent: 'chat', amount: null, type: null, status: null, description: text, customCode: '', transactionDate: new Date().toISOString().slice(0, 10) } }];
}

const wantsFinance = (/lan[cç]ar|despesa|gasto|\bpaguei\b|\brecebi\b|\bcomprei\b|\bganho\b|\blucro\b|\breceita\b|contas?\s+para\s+pagar|lan[cç]amento|gest[aã]o\s+financeira/i.test(text)
  && /(r\$\s*\d+|\d+[.,]\d{2}|\b\d{1,6}\s*reais?\b|\b\d{1,6}\b)/i.test(text))
  || (/r\$\s*\d+/i.test(text) && /despesa|gasto|receita|pagar|lan[cç]ar|ganho|lucro/i.test(text));

const wantsCode = /(?:gerar|criar|gera|crie|faz(?:er)?)\s+(?:um\s+)?c[oó]digo/i.test(text)
  || /\bc[oó]digo\s+(?:de\s+)?(?:registro|convite|manual|ativa)/i.test(text)
  || /\bKING-[A-Z0-9]{2,30}\b/i.test(text);

const wantsDiag = /\b(diagn[oó]stico|health|status\s+do\s+site|site\s+caiu|\/status)\b/i.test(text)
  || /^(status|diagn[oó]stico)$/i.test(text);

if (wantsFinance) intent = 'finance';
else if (wantsCode) intent = 'code';
else if (wantsDiag) intent = 'diag';

let amount = null;
const am = text.match(/r\$\s*(\d+[.,]?\d*)/i)
  || text.match(/(\d+[.,]\d{2})/)
  || text.match(/\b(\d{1,6})\s*reais?\b/i)
  || (intent === 'finance' ? text.match(/\b(\d{1,6})\b/) : null);
if (am) amount = parseFloat(String(am[1]).replace(',', '.'));

// ganho/lucro/receita/recebi = INCOME; default EXPENSE
let type = /\b(ganho|lucro|receita|recebi|entrou|ganhei|entrada)\b/i.test(text) ? 'INCOME' : 'EXPENSE';
let status = /\bpaguei\b|\bpago\b|j[aá]\s*paguei|j[aá]\s*recebi/i.test(text) ? 'PAID' : 'PENDING';
let description = text.replace(/r\$\s*\d+[.,]?\d*/ig, '').replace(/\s+/g, ' ').trim().slice(0, 180) || 'Lançamento via Telegram';

let customCode = '';
const cm = text.match(/\b(KING-[A-Z0-9]{2,30})\b/i)
  || text.match(/(?:gerar|criar|gera|crie)\s+c[oó]digo\s+([A-Z0-9][-_A-Z0-9]{2,30})/i);
if (cm) customCode = String(cm[1]).replace(/\s+/g, '').toUpperCase().slice(0, 32);

const today = new Date().toISOString().slice(0, 10);
return [{ json: { ...$json, intent, amount, type, status, description, customCode, transactionDate: today } }];

const prev = $input.first().json;
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const name = prev.firstName || 'olá';
const text = String(prev.text || '').trim();
const chatId = String(prev.chatId || '');

const KB = `CONHECIMENTO CONECTA KING:\n- Cartão/perfil digital + NFC. Sem app. Tag: https://tag.conectaking.com.br/{slug}\n- Site: https://www.conectaking.com.br | Login /login | Registro /registro (precisa código) | Senha /recuperar-senha\n- Entrega: cartão virtual, finanças, formulários, King Selection, Bíblia, docs, PIX\n- Planos ref.: Start 70, Prime 100, Essential 150, Finance 170, Finance Plus 200, Premium Plus 220, Corporate 230 (mensal; anual ~-20%). Confirme no site.\n- Código de acesso: só o King/admin libera.`;

function memory() {
  const store = $getWorkflowStaticData('global');
  if (!store.chats) store.chats = {};
  if (!store.chats[chatId]) store.chats[chatId] = [];
  return store.chats[chatId];
}
function pushMem(role, content) {
  const m = memory();
  m.push({ role, content: String(content || '').slice(0, 1500) });
  while (m.length > 12) m.shift();
}

const CLIENT_SYSTEM = `Você é o Assistente do Conecta King no Telegram.\nCordial, claro, PT-BR.\n\n${KB}\n\nRegras:\n- Responda o que o cliente perguntou (produto, planos, login, o que entrega).\n- NÃO invente códigos. NÃO diga que criou código.\n- Se pedirem humano/King/pessoa: confirme aviso e termine com ESCALATE:YES\n- Senão termine com ESCALATE:NO\n- Máx ~1200 caracteres.`;

let msg = '';
let escalate = /humano|falar com o king|atendente|pessoa real/i.test(text);

try {
  if (!openaiKey) {
    msg = `Olá, ${name}! Sou o Assistente do Conecta King.\nSite: https://www.conectaking.com.br\nLogin: https://www.conectaking.com.br/login\nPara humano: falar com o King.`;
  } else {
    const prefix = prev.hadVoice ? '[transcrito de áudio] ' : '';
    pushMem('user', prefix + text);
    const history = memory().slice(-10);
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: { Authorization: 'Bearer ' + openaiKey, Accept: 'application/json', 'Content-Type': 'application/json' },
      body: { model, temperature: 0.45, max_tokens: 700, messages: [{ role: 'system', content: CLIENT_SYSTEM }, ...history] },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (r.statusCode >= 200 && r.statusCode < 300) {
      let content = String(r.body?.choices?.[0]?.message?.content || '').trim();
      if (/ESCALATE:\s*YES/i.test(content)) escalate = true;
      content = content.replace(/\n?ESCALATE:\s*(YES|NO)\s*$/i, '').trim();
      msg = content || `Olá, ${name}! Como posso ajudar?`;
      pushMem('assistant', msg);
    } else {
      msg = 'IA instável agora. Tente de novo ou diga "falar com o King".';
    }
  }
} catch (e) {
  msg = 'Falha temporária. Digite "falar com o King" para aviso humano.';
}

return [{ json: { ...prev, outMessage: msg, escalate: !!escalate } }];

const prev = $input.first().json;
const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const text = String(prev.text || '').trim();
const chatId = String(prev.chatId || '');
const hadVoice = !!prev.hadVoice;

// HTTP helper para Conecta King API
async function ck(method, path, body) {
  const opts = {
    method,
    url: base + path,
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      ...(token ? { 'Authorization': 'Bearer ' + token } : {})
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

// HTTP helper para OpenAI API
async function openaiCall(payload) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + openaiKey,
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: payload,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
}

// Armazenamento de memória no staticData global
const store = $getWorkflowStaticData('global');
if (!store.chats) store.chats = {};
if (!store.chats[chatId]) {
  store.chats[chatId] = {
    history: [],
    lastCreatedTransactions: []
  };
}
const session = store.chats[chatId];
if (!session.history) session.history = [];
if (!session.lastCreatedTransactions) session.lastCreatedTransactions = [];

// Helper para encontrar ID do perfil financeiro
async function resolveProfileId() {
  try {
    const r = await ck.call(this, 'GET', '/api/finance/profiles');
    const list = (r.body && (r.body.data || r.body.profiles || r.body)) || [];
    const arr = Array.isArray(list) ? list : [];
    const primary = arr.find(p => p && (p.is_primary === true || p.isPrimary === true));
    const active = arr.find(p => p && (p.is_active !== false && p.isActive !== false));
    const pick = primary || active || arr[0];
    return pick ? Number(pick.id) : null;
  } catch (_) {
    return null;
  }
}

